import{bV as e,aL as r,u as o,G as a}from"./chunks/framework.DvBUyM1S.js";const b=JSON.parse('{"title":"大模型 API 对公结算选型清单（2026-09）","description":"","frontmatter":{"id":"PB-20260904-003","type":"playbook","title":"大模型 API 对公结算选型清单（2026-09）","tags":["llm","api-relay","enterprise-billing","fapiao"],"status":"draft","source":"web-collected:2026-09-04","created":"2026-09-04T00:00:00.000Z","updated":"2026-09-04T00:00:00.000Z"},"headers":[],"relativePath":"playbooks/llm-api-enterprise-billing.md","filePath":"playbooks/llm-api-enterprise-billing.md"}'),d={name:"playbooks/llm-api-enterprise-billing.md"};function l(i,t,n,s,h,p){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="大模型-api-对公结算选型清单-2026-09" tabindex="-1">大模型 API 对公结算选型清单（2026-09） <a class="header-anchor" href="#大模型-api-对公结算选型清单-2026-09" aria-label="Permalink to &quot;大模型 API 对公结算选型清单（2026-09）&quot;">​</a></h1><blockquote><p>来源：2026-09-04 全网检索（平台官方文档 / 帮助中心 + 多篇横评）。 <strong>强时效</strong>：中转行业政策、主体、价格变极快，付款前必须客服书面确认。 See Also：PB-20260903-001（免费额度向，本条是付费合规向）。</p></blockquote><h2 id="_1-先分清三条路" tabindex="-1">1. 先分清三条路 <a class="header-anchor" href="#_1-先分清三条路" aria-label="Permalink to &quot;1. 先分清三条路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路线</th><th>能否对公</th><th>能否开专票</th><th>风险</th></tr></thead><tbody><tr><td>官方直连（云厂商 / OpenAI Enterprise）</td><td>天然支持</td><td>是</td><td>低，但海外需外汇 + 无中文合同</td></tr><tr><td>国内合规中转 / 聚合平台</td><td>部分支持</td><td>部分支持</td><td>中，需验主体与通道是否正品</td></tr><tr><td>个人中转站</td><td>否</td><td>否</td><td>高，随时跑路，财务无法入账</td></tr></tbody></table><p>一句话结论：<strong>要报销就别碰个人中转站</strong>，它解决的是「有没有」，不解决「能不能入账」。</p><h2 id="_2-官方直连-最稳-零合规风险" tabindex="-1">2. 官方直连（最稳，零合规风险） <a class="header-anchor" href="#_2-官方直连-最稳-零合规风险" aria-label="Permalink to &quot;2. 官方直连（最稳，零合规风险）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>对公能力</th><th>备注</th></tr></thead><tbody><tr><td>阿里云百炼 / 腾讯云混元 / 火山方舟 / 百度千帆 / 华为云</td><td>标准对公 + 专票</td><td>国内主体，合同、发票、账单全流程成熟，企业采购无摩擦</td></tr><tr><td>硅基流动 SiliconFlow</td><td>支持对公转账 + 增值税发票</td><td>开源模型聚合，一个 Key 切多家</td></tr><tr><td>DeepSeek 官方</td><td>对公开票</td><td>中文/代码/推理性价比高</td></tr><tr><td>OpenAI（API Enterprise 方案）</td><td><strong>只有 Enterprise 给 invoice</strong>，支持电汇 / PO</td><td>官方帮助中心明确：个人或 Team 客户<strong>不提供发票</strong>，只走预付点数或信用卡扣款</td></tr><tr><td>OpenAI ChatGPT Business / Pro（含 Codex 席位）</td><td><strong>不支持</strong>发票 / PO / 电汇，只能信用卡或借记卡</td><td>要发票、采购单、银行转账，必须走销售表单签 Enterprise</td></tr><tr><td>Anthropic / Google Cloud</td><td>企业合同支持发票与电汇，自助档仅信用卡</td><td>同上，需走销售</td></tr></tbody></table><p>关键坑：<strong>ChatGPT Business 里的 Codex 席位按席位计费，自助购买只认卡</strong>。想让 Codex 走对公，只有两条路 —— 签 OpenAI Enterprise，或改用支持 Anthropic/OpenAI 协议的中转平台。</p><h2 id="_3-国内中转-聚合-有公开文档可核实的" tabindex="-1">3. 国内中转 / 聚合（有公开文档可核实的） <a class="header-anchor" href="#_3-国内中转-聚合-有公开文档可核实的" aria-label="Permalink to &quot;3. 国内中转 / 聚合（有公开文档可核实的）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>对公 / 发票</th><th>已核实的细节</th></tr></thead><tbody><tr><td>CloseAI</td><td>对公转账 + 增值税普票 / 专票</td><td>官方文档最完整：企业认证（对公打款 1 元内随机金额回填 或 法人扫脸）→ 在线签约等同合同 → 系统分配<strong>专属对公账户</strong>，到账自动入账（宣称 5-10 分钟）；发票按已消费完订单自动开具，7 个工作日；支持提前开票（限企业实名）；对账单可下 PDF / CSV；支付宝渠道只支持普票不支持专票</td></tr><tr><td>DMXAPI</td><td>公对公付款 + 6% 普票 / 专票</td><td>官网写明发票项目为「信息服务费」或「技术服务费」；支持<strong>先票后款</strong>（企业资质审核通过后）与先款后票两种模式</td></tr></tbody></table><p>判断标准：看<strong>官方文档 / 帮助中心有没有独立的「企业采购 / 发票」章节</strong>，且写清了认证方式、开票税目、时效。只有营销文案的，一律降权。</p><h2 id="_4-只有横评软文背书的-需自行核实" tabindex="-1">4. 只有横评软文背书的（需自行核实） <a class="header-anchor" href="#_4-只有横评软文背书的-需自行核实" aria-label="Permalink to &quot;4. 只有横评软文背书的（需自行核实）&quot;">​</a></h2><p>以下在 2026 年的多篇横评中被列为「支持对公 + 专票」，但<strong>证据多为 SEO 稿件，未见官方独立文档</strong>，打款前必须向客服索取：公司全称 + 对公账户 + 发票税目 + 开票时效。</p><ul><li>302.AI</li><li>星链 4SAPI</li><li>词元之河 TokenRiver</li><li>诗云 API / 快米兔</li><li>非线智能 nonelinear</li><li>GreatRouter</li></ul><p><strong>识别软文的方法</strong>：同一家站点批量发「XX 平台首选 / 权威实测 / 评测驱动」文章，正文里平台 A/B/C/D 用字母匿名、唯独自家实名且全维度第一 —— 这类内容只能当线索，不能当证据。本次检索中「非线智能」的 blogs 站即为此模式。</p><h2 id="_5-打款前必验的-5-件事" tabindex="-1">5. 打款前必验的 5 件事 <a class="header-anchor" href="#_5-打款前必验的-5-件事" aria-label="Permalink to &quot;5. 打款前必验的 5 件事&quot;">​</a></h2><ol><li><strong>主体一致</strong>：要平台提供公司全称，去企查查 / 天眼查核主体存续，确认收款户名 = 合同主体 = 开票主体。</li><li><strong>税目与类型</strong>：确认能开「增值税专用发票」（普票不能抵扣进项税），税目是「信息服务费」还是「技术服务费」，财务认哪个提前问清。</li><li><strong>先票后款 vs 先款后票</strong>：严格财务制度要求凭票付款，先确认平台支不支持先票后款，不支持就得走预付款流程。</li><li><strong>通道是否正品</strong>：问清是官方 API 直连还是逆向 / 共享账号封装。逆向接口随时被风控封禁，生产环境不可接受。</li><li><strong>账单粒度</strong>：后台能否导出每次调用的输入 / 输出 / 缓存 token 明细（PDF + CSV）。没有明细 = 无法按项目分摊成本 = 审计过不了。</li></ol><p>补充：确认 SLA 是否写进合同、超额 / 停服的赔付条款、余额是否可退。</p><h2 id="_6-通用踩坑" tabindex="-1">6. 通用踩坑 <a class="header-anchor" href="#_6-通用踩坑" aria-label="Permalink to &quot;6. 通用踩坑&quot;">​</a></h2><ol><li><strong>充值前先跑通财务流程</strong>：先用小额（比如 500 元）走一遍「对公转账 → 入账 → 开票 → 报销」，全流程通了再放量。</li><li><strong>专属对公账户别打错</strong>：部分平台为每家企业分配独立虚拟账户，多主体认证时账户互不相通，打错需人工处理。</li><li><strong>金额必须精确</strong>：按订单含税金额打款，差一分钱都无法自动入账。</li><li><strong>消费完才开票是常态</strong>：默认规则多为「订单消费完毕后自动开票」，急着报销要先申请提前开票（通常限企业实名）。</li><li><strong>充值有效期与退款</strong>：问清余额是否过期、能否退款，写进合同。</li><li><strong>Codex / Claude Code 接入要验协议</strong>：确认平台原生兼容 OpenAI / Anthropic 协议，否则改造成本很高。</li></ol><h2 id="_7-起步路径-30-分钟" tabindex="-1">7. 起步路径（30 分钟） <a class="header-anchor" href="#_7-起步路径-30-分钟" aria-label="Permalink to &quot;7. 起步路径（30 分钟）&quot;">​</a></h2><ol><li>若只需国产模型 + 完全合规 → 直接用阿里云百炼 / 火山方舟，标准企业流程，当天可开票。</li><li>若需 GPT / Claude / Gemini + 中文合同 + 专票 → 找 CloseAI、DMXAPI 这类有官方企业采购文档的中转，先小额跑通第 5 节的 5 项核验。</li><li>若必须用 Codex 席位且要发票 → 走 OpenAI 销售表单签 Enterprise；自助 Business 档只支持信用卡，绕不过去。</li></ol>',22)])])}const c=e(d,[["render",l]]);export{b as __pageData,c as default};
